import {
  hasTubeMapBackbone,
  hasTubeMapPaths,
  tubeMapLayout,
  tubeMapReferenceLayout
} from "./chunk-63XWYNID.js";
import {
  sampleRowLayout
} from "./chunk-XR2HMGAS.js";
import {
  anchoredLayout
} from "./chunk-GJLZ2MKE.js";
import {
  orderedLayout
} from "./chunk-UAFATXYA.js";
import {
  walkRowLayout
} from "./chunk-SENPGW4O.js";
import {
  isBackbone,
  isOffReference
} from "./chunk-RJWPJCIB.js";

// src/layoutModes.ts
var FORCE_LAYOUT_LABEL = "Force-directed layout";
var hasBackbone = (graph) => graph.nodes.some(isBackbone);
var hasWalks = (graph) => hasBackbone(graph) && (graph.paths?.length ?? 0) > 1;
var hasAlleles = (graph) => hasBackbone(graph) && graph.nodes.some(isOffReference);
var LAYOUT_MODES = [
  {
    value: "auto",
    label: "Anchored",
    description: "x is reference bp, one row per stable rank. Needs rGFA tags or a reference path.",
    run: anchoredLayout,
    cutMargins: true,
    wholeWalks: false,
    available: hasBackbone,
    drawsLocally: hasBackbone,
    drawsNodes: true
  },
  {
    value: "samplerows",
    label: "Sample rows",
    description: "x is reference bp, one row per contributing assembly. Needs rGFA tags or a reference path.",
    run: sampleRowLayout,
    cutMargins: true,
    wholeWalks: false,
    available: hasAlleles,
    drawsLocally: hasAlleles,
    drawsNodes: true
  },
  {
    value: "walkrows",
    label: "Walk rows",
    description: "x is each walk's own bp: one bar per haplotype, blue on the reference's path and purple off it, so a repeat expansion reads as bar length, and each bar boxes its haplotype's own genes where the session has them. Needs a reference and two or more walks.",
    run: walkRowLayout,
    cutMargins: false,
    wholeWalks: true,
    available: hasWalks,
    drawsLocally: hasWalks,
    drawsNodes: false
  },
  {
    value: "ordered",
    label: "Ordered",
    description: "x is reference order, not bp: every node gets room, bubbles read as lenses. Needs rGFA tags or a reference path.",
    run: orderedLayout,
    cutMargins: false,
    wholeWalks: false,
    available: hasBackbone,
    drawsLocally: hasBackbone,
    drawsNodes: true
  },
  {
    value: "tubemap",
    label: "Tube map",
    description: "sequenceTubeMap: every path a coloured tube through boxed nodes, columns in node order and node widths log-scaled. Needs P or W lines.",
    run: tubeMapLayout,
    cutMargins: false,
    wholeWalks: false,
    available: hasTubeMapPaths,
    drawsLocally: hasTubeMapPaths,
    drawsNodes: false
  },
  {
    value: "tubemapref",
    label: "Tube map on reference",
    description: "The tube map with each column at the reference bp it covers, so the tubes line up with the tracks around them. Needs P or W lines and a reference path.",
    run: tubeMapReferenceLayout,
    cutMargins: true,
    wholeWalks: false,
    available: hasTubeMapBackbone,
    drawsLocally: hasTubeMapBackbone,
    drawsNodes: false
  },
  {
    value: "force",
    label: FORCE_LAYOUT_LABEL,
    description: "OGDF FMMM (wasm) or stress, whichever engine is chosen.",
    run: () => void 0,
    cutMargins: false,
    wholeWalks: false,
    available: () => true,
    drawsLocally: () => false,
    drawsNodes: true
  }
];
var LAYOUT_MODE_VALUES = LAYOUT_MODES.map((m) => m.value);
function modeUsesLayoutEngine(value, graph) {
  return !layoutModeByValue(value).drawsLocally(graph);
}
function layoutModeByValue(value) {
  return LAYOUT_MODES.find((m) => m.value === value) ?? LAYOUT_MODES[0];
}

export {
  FORCE_LAYOUT_LABEL,
  LAYOUT_MODES,
  LAYOUT_MODE_VALUES,
  modeUsesLayoutEngine,
  layoutModeByValue
};
