import {
  bubbleSegmentIds,
  classifyBubble
} from "./chunk-AWJJSA7D.js";
import {
  svgPath
} from "./chunk-VACK24HF.js";
import {
  isBackbone
} from "./chunk-RJWPJCIB.js";

// src/bubbles/bubbleHalos.ts
var WHOLE_FRACTION = 0.9;
function coversGraph(members, nodes) {
  return members + 2 >= nodes || members >= WHOLE_FRACTION * nodes;
}
var SMALL_VARIANT_BP = 50;
function bubbleHalos(graph, bubbles, positions, repeats = []) {
  const byName = new Map(graph.nodes.map((n) => [n.name, n]));
  const halos = [];
  for (const bubble of bubbles) {
    const parts = [];
    let minX = Infinity;
    let maxX = -Infinity;
    let minY = Infinity;
    const nodeIds = [];
    const names = bubbleSegmentIds(bubble);
    for (const [i, name] of names.entries()) {
      const node = byName.get(name);
      const line = node && positions[node.id];
      if (!node || !line?.length) {
        continue;
      }
      if (bubble.key ? i === 0 || i === names.length - 1 : isBackbone(node) && (node.stable.start < bubble.start || node.stable.start >= bubble.end)) {
        continue;
      }
      nodeIds.push(node.id);
      parts.push(svgPath(line.length === 1 ? [line[0], line[0]] : line));
      for (const p of line) {
        minX = Math.min(minX, p.x);
        maxX = Math.max(maxX, p.x);
        minY = Math.min(minY, p.y);
      }
    }
    if (nodeIds.length === 0) {
      continue;
    }
    const labelAt = { x: (minX + maxX) / 2, y: minY };
    const whole = bubble.covering === true || coversGraph(nodeIds.length, graph.nodes.length);
    halos.push({
      bubble,
      ...classifyBubble(bubble, repeats),
      path: parts.join(""),
      labelAt,
      members: nodeIds.length,
      nodeIds,
      whole,
      // The drawing's own bubble keeps its name however small. A partial
      // bubble's lengths are a floor, so it may be no small variant.
      tick: !whole && !bubble.partial && bubble.longestAlleleLength < SMALL_VARIANT_BP
    });
  }
  return halos;
}

export {
  coversGraph,
  bubbleHalos
};
